INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_ISLAMIC_JINN_LORE','secondary scholarship','Classical Islamic lore of the jinn (al-Jahiz, Kitab al-Hayawan; al-Damiri, Hayat al-Hayawan; pre-Islamic Arabian tradition)','Islamic'),
 ('SRC_JEWISH_FOLKLORE','secondary scholarship','Medieval and early-modern Jewish folklore (Sefer Hasidim; East European and Lurianic demonological tradition)','Jewish Mystical')
INSERT INTO _e VALUES
 ('ENT_JM_GOLEM','Golem','Jewish Mystical','Construct','Construct','artificial life; protection; holy names; clay','B','An anthropoid of clay animated through the ritual permutation of Hebrew letters and divine names (the word emet/''truth''); Scholem traces the motif from Sefer Yetsirah speculation to the medieval Hasidei Ashkenaz and the later Prague-Maharal legend.'),
 ('ENT_JM_DYBBUK','Dybbuk','Jewish Mystical','Possessing spirit','Possessing spirit','spirit possession; the restless dead; affliction','C','A malevolent clinging spirit (Hebrew dibbuq, ''attachment'') of a dead person that possesses a living body and requires exorcism; the developed concept is early-modern (16th-17th c. Lurianic and East European folklore).'),
 ('ENT_JM_IBBUR','Ibbur','Jewish Mystical','Possessing spirit','Possessing spirit','soul impregnation; righteous indwelling; spiritual aid','B','The benevolent counterpart to the dybbuk: the temporary ''impregnation'' (ibbur) of a living person by the soul of a righteous departed one to help complete a mitzvah; a Lurianic doctrine described by Scholem, distinct from gilgul (transmigration).'),
 ('ENT_JM_ESTRIE','Estrie','Jewish Mystical','Demon','Adversarial being','blood-drinking; shape-shifting; night; harm to infants','C','A shape-shifting, blood-drinking female demon of medieval (esp. Franco-German) Jewish folklore, attested chiefly in Sefer Hasidim; the name likely derives from the Latin strix/strigae and the figure is sparsely documented.'),
 ('ENT_ISL_JINN_CLASSES','The Classes of the Jinn','Islamic','Spirit collective','Spirit collective','jinn taxonomy; classification of hidden beings','C','A grouping node for the ranked classes of jinn enumerated in classical Islamic lore (al-Jahiz, al-Damiri) — jinni, shaytan, ifrit, marid, ghul, si''lat and others; the roster and hierarchy differ between authors and are not Quranically fixed.'),
 ('ENT_ISL_SHAYTAN','Shaytan / Shayatin','Islamic','Demon class','Adversarial being','temptation; rebellion; whispering (waswasa); deception','B','The shayatin are the devils, the rebellious and tempting class of evil spirits led by Iblis; the Qur''an repeatedly names al-shaytan as humanity''s open enemy who whispers temptation.'),
 ('ENT_ISL_GHUL','Ghul','Islamic','Demon class','Adversarial being','shape-shifting; desert; deception; devouring travellers','C','The ghul (English ''ghoul''), a shape-shifting desert demon of pre-Islamic Arabian and classical Islamic lore that lures and devours lone travellers, classed among the jinn but of marginal, debated status in orthodox cosmology.'),
 ('ENT_ISL_SILAT','Si''lat','Islamic','Demon class','Adversarial being','cunning; seduction; shape-shifting; female jinn','C','The si''lat (or si''la), a cunning, often female class of jinn in classical Arabian lore, sometimes paired with or distinguished from the ghul; sparsely and inconsistently described.'),
 ('ENT_ISL_DIV','Div','Islamic','Demon class','Adversarial being','malevolence; monstrous strength; opposition to heroes','C','The div (Persian dev), a malevolent demonic being of Persianate Islamic and pre-Islamic Iranian tradition (cf. the Avestan daeva), assimilated to the jinn in Islamic-era folklore and prominent in epics such as the Shahnameh.'),
 ('ENT_CHR_GOG_AND_MAGOG','Gog and Magog','Christian','Eschatological figure','Eschatological being','eschatological war; the final assault; the nations of the end','B','Gog of the land of Magog (Ezekiel 38-39), reinterpreted in Revelation 20:8 as ''Gog and Magog,'' the nations gathered by Satan after the millennium for the final assault before their destruction by fire; modeled as a single paired eschatological entity.');
INSERT INTO entities (entity_id,canonical_name,tradition,entity_type,category,primary_domains,cult_scope,evidence_confidence,review_status,inclusion_basis,earth_association_score,chthonic_flag,serpent_flag,short_note)
INSERT INTO _s VALUES
 ('ENT_JM_GOLEM','SRC_SCHOLEM_KABBALAH','An anthropoid of clay animated through the ritual permutation of Hebrew letters and divine names (the word emet/''truth''); Scholem traces the motif from Sefer Yetsirah speculation to the medieval Hasidei Ashkenaz and the later Prague-Maharal legend.','scholarly attestation'),
 ('ENT_JM_DYBBUK','SRC_JEWISH_FOLKLORE','A malevolent clinging spirit (Hebrew dibbuq, ''attachment'') of a dead person that possesses a living body and requires exorcism; the developed concept is early-modern (16th-17th c. Lurianic and East European folklore).','scholarly attestation'),
 ('ENT_JM_IBBUR','SRC_SCHOLEM_KABBALAH','The benevolent counterpart to the dybbuk: the temporary ''impregnation'' (ibbur) of a living person by the soul of a righteous departed one to help complete a mitzvah; a Lurianic doctrine described by Scholem, distinct from gilgul (transmigration).','scholarly attestation'),
 ('ENT_JM_ESTRIE','SRC_JEWISH_FOLKLORE','A shape-shifting, blood-drinking female demon of medieval (esp. Franco-German) Jewish folklore, attested chiefly in Sefer Hasidim; the name likely derives from the Latin strix/strigae and the figure is sparsely documented.','scholarly attestation'),
 ('ENT_ISL_JINN_CLASSES','SRC_ISLAMIC_JINN_LORE','A grouping node for the ranked classes of jinn enumerated in classical Islamic lore (al-Jahiz, al-Damiri) — jinni, shaytan, ifrit, marid, ghul, si''lat and others; the roster and hierarchy differ between authors and are not Quranically fixed.','scholarly attestation'),
 ('ENT_ISL_SHAYTAN','SRC_QURAN','The shayatin are the devils, the rebellious and tempting class of evil spirits led by Iblis; the Qur''an repeatedly names al-shaytan as humanity''s open enemy who whispers temptation.','primary text attestation'),
 ('ENT_ISL_GHUL','SRC_ISLAMIC_JINN_LORE','The ghul (English ''ghoul''), a shape-shifting desert demon of pre-Islamic Arabian and classical Islamic lore that lures and devours lone travellers, classed among the jinn but of marginal, debated status in orthodox cosmology.','scholarly attestation'),
 ('ENT_ISL_SILAT','SRC_ISLAMIC_JINN_LORE','The si''lat (or si''la), a cunning, often female class of jinn in classical Arabian lore, sometimes paired with or distinguished from the ghul; sparsely and inconsistently described.','scholarly attestation'),
 ('ENT_ISL_DIV','SRC_ISLAMIC_JINN_LORE','The div (Persian dev), a malevolent demonic being of Persianate Islamic and pre-Islamic Iranian tradition (cf. the Avestan daeva), assimilated to the jinn in Islamic-era folklore and prominent in epics such as the Shahnameh.','scholarly attestation'),
 ('ENT_CHR_GOG_AND_MAGOG','SRC_HEBREW_BIBLE','Gog of the land of Magog (Ezekiel 38-39), reinterpreted in Revelation 20:8 as ''Gog and Magog,'' the nations gathered by Satan after the millennium for the final assault before their destruction by fire; modeled as a single paired eschatological entity.','primary text attestation');
