INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_ISL_SHAYTAN','member_of','ENT_ISL_JINN_CLASSES','high','The shayatin are the rebellious/evil class of jinn in Islamic cosmology.'),
 ('ENT_ISL_GHUL','member_of','ENT_ISL_JINN_CLASSES','high','Classical lore (al-Jahiz, al-Damiri) enumerates the ghul among the classes of jinn.'),
 ('ENT_ISL_SILAT','member_of','ENT_ISL_JINN_CLASSES','high','The si''lat is listed among the classes of jinn in classical Arabian demonology.'),
 ('ENT_ISL_DIV','member_of','ENT_ISL_JINN_CLASSES','medium','In Persianate Islamic tradition the div is assimilated to the jinn (a regional classification).'),
 ('ENT_ISL_IFRIT','member_of','ENT_ISL_JINN_CLASSES','high','The ifrit is a standard powerful subtype in the classical jinn taxonomy (wiring the existing entity).'),
 ('ENT_ISL_MARID','member_of','ENT_ISL_JINN_CLASSES','high','The marid is a standard rebellious/powerful subtype in the classical jinn taxonomy (wiring the existing entity).'),
 ('ENT_ISL_IBLIS','rules','ENT_ISL_SHAYTAN','high','Iblis (al-Shaytan al-rajim) is the chief of the devils; the shayatin are his host and instruments of temptation.'),
 ('ENT_ISL_SHAYTAN','presides_over','ENT_DECEPTION','high','The defining function of the shayatin is whispering temptation and deception (waswasa).'),
 ('ENT_JM_DYBBUK','member_of','ENT_JM_SHEDIM','medium','The dybbuk is broadly reckoned among harmful spirits/demons (shedim) in Jewish folk demonology, though it originates from a dead human soul.'),
 ('ENT_JM_DYBBUK','presides_over','ENT_DISEASE','medium','The dybbuk manifests as affliction/illness of the possessed host requiring exorcism.'),
 ('ENT_JM_IBBUR','opposes','ENT_JM_DYBBUK','medium','Ibbur (benevolent righteous indwelling) is the structural and moral counterpart to the dybbuk (malevolent possession) in Lurianic Kabbalah.'),
 ('ENT_JM_GOLEM','presides_over','ENT_PROTECTION','medium','In the dominant legend the golem is fashioned as a protector and servant of the Jewish community.'),
 ('ENT_JM_ESTRIE','member_of','ENT_JM_SHEDIM','medium','The estrie is a female demon of medieval Jewish folklore, classed among the harmful demonic beings (shedim).'),
 ('ENT_CHR_GOG_AND_MAGOG','presides_over','ENT_DESTRUCTION','medium','Gog and Magog embody the final eschatological assault and devastation in Ezekiel 38-39 and Revelation 20.');
